#include <stdio.h>
int main(void)  {
    // 分母保证非零；分子可为负或零，必须用 64 位整数。
    long long a, b;
    scanf("%lld%lld", &a, &b);
    // 同时变号保持分数值不变，并让最终分母为正。
    if (b < 0)  {
        a = -a;
        b = -b;
    }
    long long x = a < 0 ? -a : a;
    long long y = b;
    // 最大公约数保持余数变换不变；零分子也会得到 gcd(0,b)=b。
    while (y != 0)  {
        long long remainder = x % y;
        x = y;
        y = remainder;
    }
    // 同除正的最大公约数，输出最简分子和正分母，零自然得到 0 1。
    printf("%lld %lld\n", a / x, b / x);
    return 0;
}

