    let mut words = input.split_whitespace();
    // 分母保证非零；分子可为负或零，必须用 64 位整数。
    let mut a: i64 = words.next().unwrap().parse().unwrap();
    let mut b: i64 = words.next().unwrap().parse().unwrap();
    // 同时变号保持分数值不变，并让最终分母为正。
    if b < 0  {
        a = -a;
        b = -b;
    }
    let mut x = a.abs();
    let mut y = b;
    // 最大公约数保持余数变换不变；零分子也会得到 gcd(0,b)=b。
    while y != 0  {
        let remainder = x % y;
        x = y;
        y = remainder;
    }
    // 同除正的最大公约数，输出最简分子和正分母，零自然得到 0 1。
    println!("{} {}", a / x, b / x);
